/**
 * GET /admin/kid-manifests.json — the image size and blur-placeholder data
 * this build's kid pages were made with, for the admin Preview. Behind Access
 * with the rest of /admin/. Generated by scripts/generate-dimensions.js and
 * scripts/generate-lqip.js during prebuild.
 */
import { getCollection } from 'astro:content';
import dims from '../../data/dimensions-kids.json';
import lqip from '../../data/lqip-kids.json';

/** Keyed by image path, which holds the kid's slug: a static file any sign-in can fetch, so only published kids' are listed */
export async function GET() {
  const hidden = (await getCollection('kids', (k) => k.data.publishStatus === 'draft')).map((k) => `kids/${k.id.replace(/\.json$/, '')}/`);
  const shown = (o: Record<string, unknown>) => Object.fromEntries(Object.entries(o).filter(([k]) => !hidden.some((h) => k.startsWith(h))));
  return new Response(JSON.stringify({ dims: shown(dims), lqip: shown(lqip) }), {
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
}
